def get_body_field(*, dependant: Dependant, name: str) -> Optional[Field]:
    flat_dependant = get_flat_dependant(dependant)
    if not flat_dependant.body_params:
        return None
    first_param = flat_dependant.body_params[0]
    embed = getattr(first_param.schema, "embed", None)

    # Determine media types from the body parameters
    body_param_media_types = [
        getattr(f.schema, "media_type", "application/json") 
        for f in flat_dependant.body_params
        if hasattr(f.schema, "media_type")
    ]
    media_type = set(body_param_media_types) or {"application/json"}

    if len(flat_dependant.body_params) == 1 and not embed:
        return get_schema_compatible_field(field=first_param)

    model_name = "Body_" + name
    BodyModel = create_model(model_name)
    for f in flat_dependant.body_params:
        BodyModel.__fields__[f.name] = get_schema_compatible_field(field=f)

    required = any(f.required for f in flat_dependant.body_params)

    if any(isinstance(f.schema, params.File) for f in flat_dependant.body_params):
        BodySchema: Type[params.Body] = params.File
    elif any(isinstance(f.schema, params.Form) for f in flat_dependant.body_params):
        BodySchema = params.Form
    else:
        BodySchema = params.Body

    # Pass the media type to the BodySchema
    BodySchema_kwargs = {
        "default": None,
        "media_type": next(iter(media_type))  # Use the first media type in the set
    }

    field = Field(
        name="body",
        type_=BodyModel,
        default=None,
        required=required,
        model_config=BaseConfig,
        class_validators={},
        alias="body",
        schema=BodySchema(**BodySchema_kwargs),
    )
    return field
